class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;

    Account(String accountId, String holderName, BigDecimal balance) {
            this.accountId = accountId;
            this.holderName = holderName
            this.balance = balance;
    }
    void debit(BigDecimal amount) {
        if (balance.compareTo(amount) < 0) throw new IllegalStateException("Insufficient funds");
        balance = balance.subtract(amount);
    }
    void credit(BigDecimal amount) { balance = balance.add(amount); }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in model/Trade.java ───
class Trade {
    private final String tradeId;
    private final BigDecimal amount;
        Trade(String tradeId, BigDecimal amount) { this.tradeId = tradeId;
        this.amount = amount; }
    BigDecimal getAmount() { return amount; }
    @Override public String toString() { return tradeId + "(Rs." + amount + ")"; }
}

// ─── Would be in callback/TransferCallback.java ───
// Functional interface: exactly one abstract method, so a lambda can implement it.
@FunctionalInterface
interface TransferCallback {
    void onResult(String reference, boolean success);
}

// ─── Would be in callback/TransferListener.java ───
// Multi-method interface: a lambda CANNOT implement this; use an anonymous class.
interface TransferListener {
    void onStart(String from, String to, BigDecimal amount);
    void onComplete(String reference);
}

// ─── Would be in service/TransferService.java ───
class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());
    private TransferListener listener;
    private int counter = 0;

    void setListener(TransferListener listener) { this.listener = listener; }

    void transfer(Account from, Account to, BigDecimal amount, TransferCallback callback) {
        String reference = "TXF-" + (++counter);
        if (listener != null) listener.onStart(from.getAccountId(), to.getAccountId(), amount);
        boolean success;
        try {
            from.debit(amount);
            to.credit(amount);
            success = true;
            log.info(() -> "Transfer " + amount + " from " + from.getAccountId()
                    + " to " + to.getAccountId() + " ref=" + reference);
        } catch (RuntimeException ex) {
            success = false;
            log.log(Level.SEVERE, "Transfer failed ref=" + reference, ex);
        }
        callback.onResult(reference, success);
        if (listener != null && success) listener.onComplete(reference);
    }
}

